// ── TREND ─────────────────────────────────────────────────────
let trendView = 'aggregate';
const selectedTrendPXP = new Set(COMBO.map(c=>c.provider_payor));

function initTrendControls(){
  const root = document.getElementById('trend-pxp-legend');
  if(!root) return;
  root.innerHTML='';
  COMBO.forEach(c=>{
    const btn=document.createElement('button');
    btn.className='trend-pxp-btn active';
    btn.type='button';
    btn.dataset.pp=c.provider_payor;
    btn.innerHTML=`<span class="swatch" style="background:${PP_COLOR[c.provider_payor]||'#ff5dc0'}"></span>${c.provider_payor}`;
    btn.addEventListener('click',()=>{
      const pp=btn.dataset.pp;
      if(selectedTrendPXP.has(pp)) selectedTrendPXP.delete(pp);
      else selectedTrendPXP.add(pp);
      if(selectedTrendPXP.size===0) COMBO.forEach(x=>selectedTrendPXP.add(x.provider_payor));
      renderTrendPXPButtons();
      drawTrend();
    });
    root.appendChild(btn);
  });
  renderTrendPXPButtons();
}

function renderTrendPXPButtons(){
  document.querySelectorAll('.trend-pxp-btn').forEach(btn=>{
    btn.classList.toggle('active', selectedTrendPXP.has(btn.dataset.pp));
  });
}

function setTrendView(view,btn){
  trendView=view;
  document.querySelectorAll('[data-trend-view]').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  drawTrend();
}

function bindTrendRelayoutSync(){
  const el=document.getElementById('chart-trend');
  if(!el || el.dataset.syncBound==='1') return;
  el.dataset.syncBound='1';
  el.on('plotly_relayout', ev=>{
    const auto=ev['xaxis.autorange']===true;
    const r=ev['xaxis.range'];
    const r0=ev['xaxis.range[0]'] ?? (Array.isArray(r) ? r[0] : null);
    const r1=ev['xaxis.range[1]'] ?? (Array.isArray(r) ? r[1] : null);
    if(auto){
      applyOverviewDateFilter(null,null);
      return;
    }
    if(r0!=null && r1!=null){
      const start=normalizeDateKey(r0);
      const end=normalizeDateKey(r1);
      if(start && end){
        applyOverviewDateFilter(start,end);
      }
    }
  });
}

function getFilteredDaily(selected){
  const byDate={};
  RAW.forEach(r=>{
    if(!selected.has(r.provider_payor)) return;
    if(!byDate[r.date]) byDate[r.date]={date:r.date,total:0,successes:0,ocrSum:0,ocrN:0};
    const d=byDate[r.date];
    d.total += 1;
    if(isSuccessRow(r)) d.successes += 1;
    const ocrFromFieldTotals = (typeof r.total_field_count==='number' && r.total_field_count>0 && typeof r.complete_match_count==='number')
      ? (r.complete_match_count / r.total_field_count)
      : null;
    const ocrVal = Number.isFinite(r.ocr_accuracy) ? r.ocr_accuracy : ocrFromFieldTotals;
    if(Number.isFinite(ocrVal)){
      d.ocrSum += ocrVal;
      d.ocrN += 1;
    }
  });
  return Object.values(byDate)
    .sort((a,b)=>a.date.localeCompare(b.date))
    .map(d=>({
      date:d.date,
      total:d.total,
      success_rate:d.total ? d.successes/d.total : null,
      avg_ocr:d.ocrN ? d.ocrSum/d.ocrN : null,
    }));
}

function getFilteredDailyByCombo(selected){
  const dates=[...new Set(RAW.filter(r=>selected.has(r.provider_payor)).map(r=>r.date))].sort();
  const byCombo={};
  COMBO.forEach(c=>{ if(selected.has(c.provider_payor)) byCombo[c.provider_payor]={}; });
  RAW.forEach(r=>{
    if(!selected.has(r.provider_payor)) return;
    const pp=r.provider_payor;
    if(!byCombo[pp][r.date]) byCombo[pp][r.date]={total:0,successes:0,ocrSum:0,ocrN:0};
    const d=byCombo[pp][r.date];
    d.total += 1;
    if(isSuccessRow(r)) d.successes += 1;
    const ocrFromFieldTotals = (typeof r.total_field_count==='number' && r.total_field_count>0 && typeof r.complete_match_count==='number')
      ? (r.complete_match_count / r.total_field_count)
      : null;
    const ocrVal = Number.isFinite(r.ocr_accuracy) ? r.ocr_accuracy : ocrFromFieldTotals;
    if(Number.isFinite(ocrVal)){
      d.ocrSum += ocrVal;
      d.ocrN += 1;
    }
  });
  return Object.entries(byCombo).map(([pp,dateMap])=>({
    pp,
    points:dates.map(date=>{
      const d=dateMap[date];
      if(!d) return null;
      return {
        date,
        success_rate:d.total?d.successes/d.total:null,
        avg_ocr:d.ocrN?d.ocrSum/d.ocrN:null,
        total:d.total,
      };
    }).filter(Boolean),
  }));
}

function axisMinMax(values){
  const valid=values.filter(v=>typeof v==='number'&&!Number.isNaN(v));
  if(!valid.length) return [0,100];
  const min=+Math.min(...valid).toFixed(1);
  const max=+Math.max(...valid).toFixed(1);
  const hi=Math.min(100, Math.max(max+1.5, min+5));
  return [min, hi];
}

function summarizeFailCounts(failCounts){
  const entries=Object.entries(failCounts||{})
    .filter(([,v])=>v>0)
    .sort((a,b)=>b[1]-a[1]);
  if(!entries.length) return 'None';
  return entries.slice(0,3).map(([k,v])=>`${v} ${k}`).join(', ');
}

function getDateDetailMap(selected, onlyPP=null){
  const out={};
  RAW.forEach(r=>{
    if(!selected.has(r.provider_payor)) return;
    if(onlyPP && r.provider_payor!==onlyPP) return;
    if(!out[r.date]) out[r.date]={total:0, failCounts:{}};
    out[r.date].total += 1;
    if(!isSuccessRow(r)){
      const cat=(r.fail_category && r.fail_category.trim()) ? r.fail_category : 'Unknown';
      out[r.date].failCounts[cat]=(out[r.date].failCounts[cat]||0)+1;
    }
  });
  return out;
}

function drawTrend() {
  const selected = new Set(COMBO.map(c=>c.provider_payor).filter(pp=>selectedTrendPXP.has(pp)));
  const daily=getFilteredDaily(selected);
  const detailMap=getDateDetailMap(selected);
  const dates=daily.map(d=>d.date);
  const rates=daily.map(d=>d.success_rate!=null?+(d.success_rate*100).toFixed(1):null);
  const ocrs=daily.map(d=>d.avg_ocr!=null?+(d.avg_ocr*100).toFixed(1):null);
  const totals=daily.map(d=>d.total);
  const failSummaries=dates.map(d=>summarizeFailCounts((detailMap[d]||{}).failCounts));
  const traces=[];
  let axisRates=[...rates];
  let axisOcrs=[...ocrs];

  if(trendView==='aggregate'){
    traces.push(
      {type:'scatter', mode:'lines', name:'Success Rate', x:dates, y:rates,
        line:{color:'#ff5dc0',width:2.4},
        customdata:dates.map((_,i)=>[totals[i],failSummaries[i]]),
        hovertemplate:'<b>%{x}</b><br>Success: %{y}%<br>Rows: %{customdata[0]}<br>Top Failures: %{customdata[1]}<extra></extra>',
        yaxis:'y'},
      {type:'scatter', mode:'lines', name:'90% Threshold',
        x:[dates[0],dates[dates.length-1]], y:[90,90],
        line:{color:'rgba(255,93,192,0.35)',dash:'dot',width:1.2},
        hoverinfo:'skip', yaxis:'y'},
      {type:'scatter', mode:'lines', name:'Avg OCR Accuracy',
        x:dates, y:ocrs,
        line:{color:'#ffd166',width:2,dash:'dot',shape:'spline'},
        connectgaps:true,
        customdata:totals,
        hovertemplate:'<b>%{x}</b><br>Avg OCR: %{y}%<br>Rows: %{customdata}<extra></extra>',
        yaxis:'y2'}
    );
  } else {
    const byCombo=getFilteredDailyByCombo(selected);
    byCombo.forEach(s=>{
      const c=PP_COLOR[s.pp]||'#ff5dc0';
      const detailMapPP=getDateDetailMap(selected, s.pp);
      const sRates=s.points.map(p=>+(p.success_rate*100).toFixed(1));
      const sOcrs=s.points.map(p=>+(p.avg_ocr*100).toFixed(1));
      const sRows=s.points.map(p=>(detailMapPP[p.date]||{}).total || p.total || 0);
      const sFail=s.points.map(p=>summarizeFailCounts(((detailMapPP[p.date]||{}).failCounts)||{}));
      axisRates=axisRates.concat(sRates);
      axisOcrs=axisOcrs.concat(sOcrs);
      traces.push({
        type:'scatter', mode:'lines+markers', name:`${s.pp} — Success`,
        x:s.points.map(p=>p.date), y:sRates,
        marker:{size:4,color:c}, line:{color:c,width:2}, yaxis:'y',
        customdata:s.points.map((_,i)=>[sRows[i],sFail[i]]),
        hovertemplate:`<b>${s.pp}</b><br>%{x}<br>Success: %{y}%<br>Rows: %{customdata[0]}<br>Top Failures: %{customdata[1]}<extra></extra>`,
        showlegend:false,
      });
      traces.push({
        type:'scatter', mode:'lines+markers', name:`${s.pp} — OCR`,
        x:s.points.map(p=>p.date), y:sOcrs,
        marker:{size:4,color:c}, line:{color:c,width:1.8,dash:'dash'}, yaxis:'y2',
        connectgaps:true,
        customdata:sRows,
        hovertemplate:`<b>${s.pp}</b><br>%{x}<br>OCR: %{y}%<br>Rows: %{customdata}<extra></extra>`,
        showlegend:false,
      });
    });
  }

  const [yMin,yMax]=axisMinMax(axisRates);
  const [y2Min,y2Max]=axisMinMax(axisOcrs);
  const xRange = (overviewDateFilter.start && overviewDateFilter.end) ? [overviewDateFilter.start, overviewDateFilter.end] : undefined;

  Plotly.react('chart-trend',traces,{
    ...LB, height:240, margin:{t:14,r:80,b:46,l:90},
    xaxis:{
      ...LB.xaxis,
      type:'date',
      tickformat:'%m/%d',
      range:xRange,
      autorange:!xRange,
      tickangle:-45,
      tickfont:{size:9,color:'#6b7280'}
    },
    yaxis:{
      ...LB.yaxis,
      type:'linear',
      title:{text:'Success Rate %',standoff:18},
      automargin:true,
      range:[yMin,yMax]
    },
    yaxis2:{
      type:'linear',
      title:{text:'OCR Accuracy %',font:{size:10,color:'#ffd166'},standoff:16},
      automargin:true,
      overlaying:'y',
      side:'right',
      range:[y2Min,y2Max],
      tickfont:{size:10,color:'#ffd166'},
      gridcolor:'transparent',
      zerolinecolor:'transparent'
    },
    annotations:[],
    legend:{orientation:'h',x:0,y:1.08,font:{size:10}},
  },CFG_INTERACTIVE);
  drawTrendRows(selected);
}

function drawTrendRows(selected){
  const daily=getFilteredDaily(selected);
  const dates=daily.map(d=>d.date);
  const totals=daily.map(d=>d.total);
  const xRange=(overviewDateFilter.start && overviewDateFilter.end) ? [overviewDateFilter.start, overviewDateFilter.end] : undefined;
  Plotly.react('chart-trend-rows', [{
    type:'bar', x:dates, y:totals,
    marker:{color:'rgba(96,165,250,.75)', line:{width:1,color:'rgba(96,165,250,.95)'}},
    hovertemplate:'<b>%{x}</b><br>Total Rows: %{y}<extra></extra>',
  }], {
    ...LB, height:150, margin:{t:6,r:14,b:38,l:70},
    xaxis:{...LB.xaxis,type:'date',range:xRange,autorange:!xRange,tickformat:'%m/%d'},
    yaxis:{...LB.yaxis,title:'Rows',tickformat:''},
    showlegend:false,
  }, CFG);
}

// ── FAILURE BREAKDOWN (toggle: fail / success) ────────────────
let failView='fail';
let readinessUnit='raw';
const selectedReadinessPXP = new Set(COMBO.map(c=>c.provider_payor));

function initReadinessControls(){
  const root=document.getElementById('readiness-pxp-legend');
  if(!root || root.dataset.inited==='1') return;
  root.dataset.inited='1';
  COMBO.forEach(c=>{
    const btn=document.createElement('button');
    btn.className='trend-pxp-btn active';
    btn.type='button';
    btn.dataset.pp=c.provider_payor;
    btn.innerHTML=`<span class="swatch" style="background:${PP_COLOR[c.provider_payor]||'#ff5dc0'}"></span>${c.provider_payor.replace(' × ','<br>× ')}`;
    btn.addEventListener('click',()=>{
      const pp=btn.dataset.pp;
      if(selectedReadinessPXP.has(pp)) selectedReadinessPXP.delete(pp);
      else selectedReadinessPXP.add(pp);
      if(selectedReadinessPXP.size===0) COMBO.forEach(x=>selectedReadinessPXP.add(x.provider_payor));
      renderReadinessPXPButtons();
      drawFailBreakdown();
      drawReadinessTimeline();
    });
    root.appendChild(btn);
  });
  renderReadinessPXPButtons();
}

function renderReadinessPXPButtons(){
  document.querySelectorAll('#readiness-pxp-legend .trend-pxp-btn').forEach(btn=>{
    btn.classList.toggle('active', selectedReadinessPXP.has(btn.dataset.pp));
  });
}

function setReadinessUnit(unit,btn){
  readinessUnit=unit;
  document.querySelectorAll('[data-runit]').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  drawFailBreakdown();
  drawReadinessTimeline();
}

function classifySuccessQuality(row){
  const falseCount = Number.isFinite(row.complete_match_false_count) ? row.complete_match_false_count : 0;
  const totalFields = Number.isFinite(row.total_field_count) && row.total_field_count>0 ? row.total_field_count : null;
  if(falseCount===0) return 'Clean';
  if(!totalFields) return 'Low';
  const frac=falseCount/totalFields;
  if(frac>=0.5) return 'Severe';
  if(frac>=0.33) return 'High';
  if(frac>=0.17) return 'Moderate';
  return 'Low';
}

function drawReadinessTimeline(){
  const selected=new Set(COMBO.map(c=>c.provider_payor).filter(pp=>selectedReadinessPXP.has(pp)));
  const rows=RAW.filter(r=>selected.has(r.provider_payor));
  const dates=[...new Set(rows.map(r=>r.date))].sort();
  const totalByDate={};
  dates.forEach(d=>{totalByDate[d]=0;});
  rows.forEach(r=>{totalByDate[r.date]=(totalByDate[r.date]||0)+1;});

  const failCats=['Patient Not Found','Credential Issue','Agent Timeout','Portal/Network Error','Document Upload Failed','Delegated Auth Issue','Unknown'];
  const sucCats=['Severe','High','Moderate','Low','Clean'];
  const cats=failView==='fail' ? failCats : sucCats;
  const counts={};
  cats.forEach(c=>{counts[c]={}; dates.forEach(d=>{counts[c][d]=0;});});

  rows.forEach(r=>{
    const d=r.date;
    if(failView==='fail'){
      if(isSuccessRow(r)) return;
      const cat=(r.fail_category && r.fail_category.trim()) ? r.fail_category : 'Unknown';
      if(!(cat in counts)) counts['Unknown'][d]=(counts['Unknown'][d]||0)+1;
      else counts[cat][d]=(counts[cat][d]||0)+1;
    } else {
      if(!isSuccessRow(r)) return;
      const cat=classifySuccessQuality(r);
      counts[cat][d]=(counts[cat][d]||0)+1;
    }
  });

  const traces=cats.map(cat=>{
    const nums=dates.map(d=>counts[cat][d]||0);
    const den=dates.map(d=>totalByDate[d]||0);
    const ys=nums.map((n,i)=> readinessUnit==='prop' ? (den[i] ? n/den[i] : 0) : n);
    const sizes=ys.map((v,i)=>{
      if(readinessUnit==='prop') return 8 + (Math.max(0,v) * 38);
      return 8 + (Math.max(0,nums[i]) * 2.2);
    });
    const idxs=dates.map((_,i)=>i).filter(i=>nums[i] > 0);
    return {
      type:'scatter', mode:'markers', name:cat,
      x:idxs.map(i=>dates[i]),
      y:idxs.map(i=>ys[i]),
      marker:{
        size:idxs.map(i=>sizes[i]),
        sizemode:'diameter',
        color: failView==='fail' ? (FAIL_COLORS[cat]||'rgba(255,255,255,.4)') : (SEV_COLORS[cat]||'#3b3f4a'),
        opacity:0.85,
        line:{width:1.5,color:'rgba(255,255,255,0.18)'},
      },
      customdata:idxs.map(i=>[nums[i],den[i]]),
      hovertemplate: readinessUnit==='prop'
        ? `<b>${cat}</b><br>%{x}<br>Proportion: %{y:.1%}<br>Count: %{customdata[0]} / %{customdata[1]} rows<extra></extra>`
        : `<b>${cat}</b><br>%{x}<br>Count: %{y}<br>Rows: %{customdata[1]}<extra></extra>`,
    };
  });

  Plotly.react('chart-readiness-trend', traces, {
    ...LB, height:290, margin:{t:10,r:14,b:46,l:72},
    xaxis:{...LB.xaxis,type:'date',tickformat:'%m/%d',tickangle:-45},
    yaxis:{
      ...LB.yaxis,
      title: readinessUnit==='prop' ? 'Proportion of Daily Rows' : 'Daily Frequency',
      tickformat: readinessUnit==='prop' ? '.0%' : '',
      range: readinessUnit==='prop' ? [0,1] : undefined,
      autorange: readinessUnit!=='prop',
    },
    legend:{orientation:'h',x:0,y:1.12,font:{size:10}},
  }, CFG_INTERACTIVE);
}

function setFailView(v,btn){
  failView=v;
  document.querySelectorAll('#fail-view-toggle .tog').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  drawFailBreakdown();
  drawReadinessTimeline();
}
function drawFailBreakdown(){
  const selected=new Set(COMBO.map(c=>c.provider_payor).filter(pp=>selectedReadinessPXP.has(pp)));
  const rows=RAW.filter(r=>selected.has(r.provider_payor));
  const combos=OVERVIEW_PP_ORDER.filter(pp=>selected.has(pp));
  const totalRowsByPP={};
  combos.forEach(pp=>{totalRowsByPP[pp]=0;});
  rows.forEach(r=>{totalRowsByPP[r.provider_payor]=(totalRowsByPP[r.provider_payor]||0)+1;});

  const cats = failView==='fail'
    ? ['Patient Not Found','Credential Issue','Agent Timeout','Portal/Network Error','Document Upload Failed','Delegated Auth Issue','Unknown']
    : ['Severe','High','Moderate','Low','Clean'];
  const counts={};
  combos.forEach(pp=>{ counts[pp]={}; cats.forEach(c=>{counts[pp][c]=0;}); });

  rows.forEach(r=>{
    const pp=r.provider_payor;
    if(failView==='fail'){
      if(isSuccessRow(r)) return;
      const cat=(r.fail_category && r.fail_category.trim()) ? r.fail_category : 'Unknown';
      counts[pp][cat in counts[pp] ? cat : 'Unknown'] += 1;
    } else {
      if(!isSuccessRow(r)) return;
      const cat=classifySuccessQuality(r);
      counts[pp][cat] += 1;
    }
  });

  const comboTot={};
  combos.forEach(pp=>{ comboTot[pp]=cats.reduce((s,c)=>s+(counts[pp][c]||0),0); });
  const sorted=[...combos].filter(pp=>(totalRowsByPP[pp]||0)>0).sort((a,b)=>comboTot[b]-comboTot[a]);

  const traces=cats.map(cat=>({
    type:'bar',name:cat,orientation:'h',
    y:sorted,
    x:sorted.map(pp=>{
      const raw=counts[pp][cat]||0;
      return readinessUnit==='prop' ? (totalRowsByPP[pp] ? raw/totalRowsByPP[pp] : 0) : raw;
    }),
    customdata:sorted.map(pp=>[counts[pp][cat]||0,totalRowsByPP[pp]||0]),
    marker:{color:failView==='fail' ? (FAIL_COLORS[cat]||'rgba(255,255,255,.2)') : (SEV_COLORS[cat]||'#3b3f4a'),opacity:0.88},
    hovertemplate: readinessUnit==='prop'
      ? `<b>%{y}</b><br>${cat}: %{x:.1%}<br>Count: %{customdata[0]} / %{customdata[1]} rows<extra></extra>`
      : `<b>%{y}</b><br>${cat}: %{x}<br>Rows: %{customdata[1]}<extra></extra>`,
  }));

  const maxX = Math.max(0.01, ...traces.flatMap(t=>t.x));
  Plotly.react('chart-fail-breakdown',traces,{
    ...LB,barmode:'stack',height:300,
    margin:{t:14,r:14,b:46,l:300},
    xaxis:{
      ...LB.xaxis,
      title: readinessUnit==='prop'
        ? (failView==='fail' ? 'Hard Failure Proportion (of P×P Rows)' : 'Success Quality Proportion (of P×P Rows)')
        : (failView==='fail' ? 'Number of Hard Failures' : 'Number of Successes'),
      tickformat: readinessUnit==='prop' ? '.0%' : '',
      range: readinessUnit==='prop' ? [0,1] : [0, maxX*1.12],
      autorange:false,
    },
    yaxis:{...LB.yaxis,autorange:'reversed'},
    legend:{orientation:'h',x:0,y:-0.25,font:{size:9}},
  },CFG);
}

