function drawSFSev(){
  const ppList=[...new Set(SF_DATA.map(r=>r.provider_payor))];
  const sevOrder=['Severe','High','Moderate','Low'];
  // tally
  const tally={};
  ppList.forEach(pp=>{tally[pp]={};sevOrder.forEach(s=>{tally[pp][s]=0;});});
  SF_DATA.forEach(r=>{if(tally[r.provider_payor]) tally[r.provider_payor][r.severity]=(tally[r.provider_payor][r.severity]||0)+1;});
  // sort by total silent
  const sortedPP=ppList.sort((a,b)=>{
    const ta=sevOrder.reduce((s,k)=>s+(tally[a][k]||0),0);
    const tb=sevOrder.reduce((s,k)=>s+(tally[b][k]||0),0);
    return tb-ta;
  });
  const traces=sevOrder.map(sev=>({
    type:'bar',name:sev,orientation:'h',
    y:sortedPP,
    x:sortedPP.map(pp=>tally[pp][sev]||0),
    marker:{color:SEV_COLORS[sev],opacity:.88},
    hovertemplate:'<b>%{y}</b><br>'+sev+': %{x}<extra></extra>',
  }));
  const maxT=Math.max(...sortedPP.map(pp=>sevOrder.reduce((s,k)=>s+(tally[pp][k]||0),0)));
  Plotly.newPlot('chart-sf-sev',traces,{
    ...LB,barmode:'stack',height:270,
    margin:{t:14,r:14,b:55,l:300},
    xaxis:{...LB.xaxis,title:'# Silent Failures',tickmode:'linear',tick0:0,dtick:20,range:[0,maxT+10],autorange:false},
    yaxis:{...LB.yaxis,autorange:'reversed'},
    legend:{orientation:'h',x:0,y:-0.25,font:{size:9}},
  },CFG);
}

