function setSev(btn,sev){
  sfSev=sev;
  document.querySelectorAll('[data-sev]').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  filterSFTable();
}
function filterSFTable(){
  const combo=document.getElementById('sf-filter-combo').value;
  const search=document.getElementById('sf-search').value.toLowerCase();
  sfTable.setFilter(row=>{
    if(combo&&row.provider_payor!==combo)return false;
    if(sfSev&&row.severity!==sfSev)return false;
    if(search&&!JSON.stringify(row).toLowerCase().includes(search))return false;
    return true;
  });
  updateSFCount();
}
function resetSF(){
  document.getElementById('sf-filter-combo').value='';
  document.getElementById('sf-search').value='';
  sfSev='';
  document.querySelectorAll('[data-sev]').forEach(b=>b.classList.remove('active'));
  document.querySelector('[data-sev=""]').classList.add('active');
  sfTable.clearFilter();
  updateSFCount();
}
function updateSFCount(){
  setTimeout(()=>{const c=sfTable?sfTable.getDataCount():SF_DATA.length;document.getElementById('sf-count').textContent=c+' of '+SF_DATA.length+' rows';},100);
}

