function filterMain(){
  const dba=document.getElementById('f-dba').value;
  const name=document.getElementById('f-name').value;
  const status=document.getElementById('f-status').value;
  const failcat=document.getElementById('f-failcat').value;
  const search=document.getElementById('f-search').value.toLowerCase();
  mainTable.setFilter(row=>{
    if(dba&&row.dba!==dba)return false;
    if(name&&row.name!==name)return false;
    if(status&&row.agent_status!==status)return false;
    if(failcat&&row.fail_category!==failcat)return false;
    if(search&&!JSON.stringify(row).toLowerCase().includes(search))return false;
    return true;
  });
  updateMainCount();
}
function resetMain(){
  ['f-dba','f-name','f-status','f-failcat'].forEach(id=>document.getElementById(id).value='');
  document.getElementById('f-search').value='';
  mainTable.clearFilter();
  updateMainCount();
}
function updateMainCount(){
  setTimeout(()=>{const c=mainTable?mainTable.getDataCount():RAW.length;document.getElementById('main-count').textContent=c+' of '+RAW.length+' rows';},100);
}

// ── NAV ───────────────────────────────────────────────────────
let inited={};
function showSection(id,btn){
  document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
  const sectionEl = document.getElementById('section-'+id);
  if (sectionEl) sectionEl.classList.add('active');
  if (btn) btn.classList.add('active');
  if(!inited[id]){
    inited[id]=true;
    if(id==='overview'){ drawHeatmap();drawBar();drawTrend(); }
    else if(id==='readiness'){ drawFailBreakdown(); initReadinessControls(); drawReadinessTimeline(); if(!sfTable)buildSFTable(); }
    else if(id==='recommendations'){ buildRecTable(); }
    else if(id==='silent'){ drawSFRate();drawSFSev();drawSFDonut();drawSFHist(); if(!sfTable)buildSFTable(); }
    else if(id==='data'){ if(!mainTable)buildMainTable(); }
  }
}

document.addEventListener('DOMContentLoaded',()=>{
  const page = window.DASHBOARD_PAGE || 'overview';
  inited[page] = true;
  if (page === 'overview') {
    initTrendControls();
    drawHeatmap(); drawBar(); drawTrend();
    bindTrendRelayoutSync();
    bindKeyPatternHoverTimeline();
  } else if (page === 'readiness') {
    drawFailBreakdown(); initReadinessControls(); drawReadinessTimeline(); if (!sfTable) buildSFTable();
  } else if (page === 'recommendations') {
    buildRecTable();
  } else if (page === 'silent') {
    drawSFRate(); drawSFSev(); drawSFDonut(); drawSFHist(); if (!sfTable) buildSFTable();
  } else if (page === 'data') {
    if (!mainTable) buildMainTable();
  }
});
